import React from 'react';
import JsBarcode from 'jsbarcode';
import { getPriceFormat } from '../../../core/utils';

export const LABEL_PAGE_STYLE = `
  @page { size: 50mm 25mm; margin: 0; }
  html, body { margin: 0 !important; padding: 0 !important; }
`;

// Generate before opening the print dialog, so invalid codes cannot print blank labels.
export const createBarcode = (code: string): string => {
  if (!code || !/^[\x20-\x7E]+$/.test(code)) {
    throw new Error('The product code must contain printable English letters, numbers or symbols to print a barcode.');
  }
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  JsBarcode(svg, code, {
    format: 'CODE128',
    displayValue: false,
    width: 2,
    height: 60,
    margin: 20,
    marginTop: 0,
    marginBottom: 0,
    background: '#ffffff',
    lineColor: '#000000',
  });
  const width = parseFloat(svg.getAttribute('width') || '0');
  svg.setAttribute('viewBox', `0 0 ${width} 60`);
  svg.setAttribute('width', '46mm');
  svg.setAttribute('height', '13mm');
  svg.setAttribute('preserveAspectRatio', 'none');
  return svg.outerHTML;
};

interface LabelPrintProps {
  code: string;
  price: number;
  currencyCode: string;
  barcode: string;
}

export const LabelPrint = React.forwardRef<HTMLDivElement, LabelPrintProps>(
  ({ code, price, currencyCode, barcode }, ref) => (
    <div
      ref={ref}
      style={{
        width: '50mm', height: '25mm', boxSizing: 'border-box',
        padding: '2mm', background: '#fff', color: '#000',
        display: 'flex', flexDirection: 'column', alignItems: 'center',
        justifyContent: 'center', fontFamily: 'Arial, sans-serif',
        breakInside: 'avoid', overflow: 'hidden',
      }}
    >
      <div
        // This SVG is generated locally by JsBarcode, never supplied as HTML by the API.
        dangerouslySetInnerHTML={{ __html: barcode }}
        style={{ width: '46mm', height: '13mm', flexShrink: 0 }}
      />
      <div style={{ fontSize: '8pt', lineHeight: '3.5mm', textAlign: 'center', overflowWrap: 'anywhere' }}>{code}</div>
      <div style={{ fontSize: '9pt', lineHeight: '4mm', fontWeight: 700, whiteSpace: 'nowrap' }}>
        {getPriceFormat(price, currencyCode)}
      </div>
    </div>
  )
);
LabelPrint.displayName = 'LabelPrint';
